<?php require '../../config/db.php';require '../../includes/functions.php';require '../../includes/auth.php';require_admin();if(!csrf_ok($_POST['csrf']??''))json_response(false,'Security token expired.',[],419);$pid=(int)($_POST['product_id']??0);$type=$_POST['type']??'';$qty=(int)($_POST['quantity']??0);if(!$pid||!in_array($type,['IN','OUT'])||$qty<1)json_response(false,'Select a product and valid quantity.',[],422);$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT quantity FROM products WHERE id=? FOR UPDATE');$q->execute([$pid]);$before=(int)$q->fetchColumn();$after=$type==='IN'?$before+$qty:$before-$qty;if($after<0)throw new Exception('Stock out quantity exceeds available stock.');$pdo->prepare('UPDATE products SET quantity=? WHERE id=?')->execute([$after,$pid]);$pdo->prepare('INSERT INTO stock_transactions(product_id,type,quantity,stock_before,stock_after,reason,reference_no,user_id) VALUES(?,?,?,?,?,?,?,?)')->execute([$pid,$type,$qty,$before,$after,trim($_POST['reason']??''),trim($_POST['reference_no']??''),admin_user()['id']]);$pdo->commit();json_response(true,'Stock movement saved successfully.');}catch(Throwable $e){$pdo->rollBack();json_response(false,$e->getMessage(),[],422);}